typedef enum {
    Z_DENTRY_TAG_ROOT,
    Z_DENTRY_TAG_NOTFOUND,
    Z_DENTRY_TAG_FILE,
    Z_DENTRY_TAG_DIRECTORY,
    Z_DENTRY_TAG_MOUNT,
} z_t399_tag_t;
typedef struct {
    uint8_t tag;
    union {
        z_t400_t notfound;
        z_t409_t file;
        z_t414_t directory;
        z_t419_t mount;
    } data;
} z_t399_t;
static bool z_t399_eq(z_t399_t a, z_t399_t b) {
    if (a.tag != b.tag) return false;
    switch (a.tag) {
        case Z_DENTRY_TAG_NOTFOUND: return z_t400_eq(a.data.notfound, b.data.notfound);
        case Z_DENTRY_TAG_FILE: return z_t409_eq(a.data.file, b.data.file);
        case Z_DENTRY_TAG_DIRECTORY: return z_t414_eq(a.data.directory, b.data.directory);
        case Z_DENTRY_TAG_MOUNT: return z_t419_eq(a.data.mount, b.data.mount);
        default: return true;
    }
}

